        assertThatThrownBy(() -> Validation.zipWith(Validation.<String, Integer>valid(1), Validation.<String, Integer>valid(2), Validation.<String, Integer>valid(3), (a1, a2, a3) -> null)).isInstanceOf(NullPointerException.class).hasMessage("Validation.zipWith: f returned null");
