    @Test
    public void shouldZip6Valids() {
        assertThat(Validation.zip(Validation.<String, Integer>valid(1), Validation.<String, Integer>valid(2), Validation.<String, Integer>valid(3), Validation.<String, Integer>valid(4), Validation.<String, Integer>valid(5), Validation.<String, Integer>valid(6))).isEqualTo(Validation.valid(Tuple.of(1, 2, 3, 4, 5, 6)));
    }

    @Test
    public void shouldZipWith6Valids() {
        final AtomicInteger calls = new AtomicInteger();
        final Validation<String, String> actual = Validation.zipWith(Validation.<String, Integer>valid(1), Validation.<String, Integer>valid(2), Validation.<String, Integer>valid(3), Validation.<String, Integer>valid(4), Validation.<String, Integer>valid(5), Validation.<String, Integer>valid(6), (a1, a2, a3, a4, a5, a6) -> {
            calls.incrementAndGet();
            return "" + a1 + a2 + a3 + a4 + a5 + a6;
        });
        assertThat(actual).isEqualTo(Validation.valid("123456"));
        assertThat(calls.get()).isEqualTo(1);
    }

