    @Test
    public void shouldZip7Valids() {
        assertThat(Validation.zip(Validation.<String, Integer>valid(1), Validation.<String, Integer>valid(2), Validation.<String, Integer>valid(3), Validation.<String, Integer>valid(4), Validation.<String, Integer>valid(5), Validation.<String, Integer>valid(6), Validation.<String, Integer>valid(7))).isEqualTo(Validation.valid(Tuple.of(1, 2, 3, 4, 5, 6, 7)));
    }

    @Test
    public void shouldZipWith7Valids() {
        final AtomicInteger calls = new AtomicInteger();
        final Validation<String, String> actual = Validation.zipWith(Validation.<String, Integer>valid(1), Validation.<String, Integer>valid(2), Validation.<String, Integer>valid(3), Validation.<String, Integer>valid(4), Validation.<String, Integer>valid(5), Validation.<String, Integer>valid(6), Validation.<String, Integer>valid(7), (a1, a2, a3, a4, a5, a6, a7) -> {
            calls.incrementAndGet();
            return "" + a1 + a2 + a3 + a4 + a5 + a6 + a7;
        });
        assertThat(actual).isEqualTo(Validation.valid("1234567"));
        assertThat(calls.get()).isEqualTo(1);
    }

