    @Test
    public void shouldZip8Valids() {
        assertThat(Validation.zip(Validation.<String, Integer>valid(1), Validation.<String, Integer>valid(2), Validation.<String, Integer>valid(3), Validation.<String, Integer>valid(4), Validation.<String, Integer>valid(5), Validation.<String, Integer>valid(6), Validation.<String, Integer>valid(7), Validation.<String, Integer>valid(8))).isEqualTo(Validation.valid(Tuple.of(1, 2, 3, 4, 5, 6, 7, 8)));
    }

    @Test
    public void shouldZipWith8Valids() {
        final AtomicInteger calls = new AtomicInteger();
        final Validation<String, String> actual = Validation.zipWith(Validation.<String, Integer>valid(1), Validation.<String, Integer>valid(2), Validation.<String, Integer>valid(3), Validation.<String, Integer>valid(4), Validation.<String, Integer>valid(5), Validation.<String, Integer>valid(6), Validation.<String, Integer>valid(7), Validation.<String, Integer>valid(8), (a1, a2, a3, a4, a5, a6, a7, a8) -> {
            calls.incrementAndGet();
            return "" + a1 + a2 + a3 + a4 + a5 + a6 + a7 + a8;
        });
        assertThat(actual).isEqualTo(Validation.valid("12345678"));
        assertThat(calls.get()).isEqualTo(1);
    }

